   *  the screen shows the sheet as it is. Kept for this screen only, across sheet loads. */
  readonly asOf = signal<string | null>(null);

  signIn(name: string): boolean {
    const n = name.trim();
    if (!n) return false;
    this.user.set(n);
    return true;
  }

